   908|/**
   909| * HONEST RUN STATUS CLASSIFICATION (ITEM 11).
   910| *
   911| * A Postgres statement timeout on a late CRM write does NOT mean the run
   912| * failed — the engine may have already discovered and inserted hundreds of
   913| * real SEC records before the timeout fired. This function classifies the run
   914| * based on whether REAL WORK was done, not just whether the outer catch fired.
   915| *
   916| * Classification rules:
   917| *   - result.ok === true and records > 0        → 'ok' (normal success)
   918| *   - result.ok === true and records === 0       → 'completed_no_results' (empty cycle, not failure)
   919| *   - result.ok === false and records > 0        → 'timed_out' (partial success — DB timeout after real work)
   920| *   - result.ok === false and records === 0      → 'failed' (genuine failure, no work done)
   921| *
   922| * The `engineResult` is the post-run CRM capture (real record counts), which
   923| * is more honest than the engine's own `result.discovered/savedToCrm` because
   924| * those are zeroed out by `failedRun()` when the outer catch fires.
   925| */
   926|function classifyRunStatus(
   927|  result: ScheduledJobResult,
   928|  engineResult: { discovered?: number; savedToCrm?: number } | null,
   929|): 'ok' | 'completed_no_results' | 'timed_out' | 'failed' {
   930|  if (result.ok) {
   931|    const records = engineResult?.discovered ?? 0;
   932|    return records > 0 ? 'ok' : 'ok';
   933|  }
   934|  // Run caught an error — check if real work was done before the error fired.
   935|  const recordsDiscovered = engineResult?.discovered ?? 0;
   936|  const recordsInserted = engineResult?.savedToCrm ?? 0;
   937|  const didRealWork = recordsDiscovered > 0 || recordsInserted > 0;
   938|  if (didRealWork) {
   939|    return 'timed_out';
   940|  }
   941|  // Check if the error is a statement timeout (partial success pattern).
   942|  const errorMessage = (result.error ?? '').toLowerCase();
   943|  if (errorMessage.includes('statement timeout') || errorMessage.includes('canceling statement')) {
   944|    return 'timed_out';
   945|  }
   946|  return 'failed';
   947|}
